"""Static-native WO4 facts; generated bytes are not a playable save."""
from dataclasses import replace
from functools import lru_cache
import os
from pathlib import Path
import struct
import tempfile
import unittest
from unittest.mock import patch

from koei_editor.games.dw3.models import SaveError
from koei_editor.games.wo4 import codec, parser as p
from koei_editor.shared.adapter_contract import BoundScalarAdapter


@lru_cache(maxsize=1)
def generated_raw():
    system = bytearray((i * 17 + 31) & 255 for i in range(codec.SYSTEM_PAYLOAD_SIZE))
    struct.pack_into('<III', system, 0, p.REVISION, 0, 0)
    struct.pack_into('<IIHHI', system, p.SYSTEM_GLOBAL + 0xCC, 12345, 23456, 123, 231, 4567)
    for element in range(64):
        struct.pack_into('<H', system, p.SYSTEM_GLOBAL + 0xE6 + element * 2,
                         (0, 8, 999, 1001)[element % 4])
    play = bytes((i * 13 + 23) & 255 for i in range(codec.PLAY_PAYLOAD_SIZE))
    blocks = (codec.Block(1, 0, 0x12345678, bytes(system), bytes(range(12))),
              codec.Block(0, codec.SYSTEM_BLOCK_SIZE, 0x87654321, play, b'\xa7'))
    return codec.encode(blocks)


def repack(payload):
    payload = bytes(payload)
    blocks = codec.decode(generated_raw())
    return codec.encode((replace(blocks[0], payload=payload[:codec.SYSTEM_PAYLOAD_SIZE]),
                         replace(blocks[1], payload=payload[codec.SYSTEM_PAYLOAD_SIZE:])))


class WO4CodecTests(unittest.TestCase):
    def test_independent_ordered_double_key_and_iv_answers(self):
        for index in (0, 1):
            x = (index + 1) * 0.5 * 0.5
            for _ in range(10):
                x = (3.66 * x) * (1.0 - x)
            seed = struct.unpack('<I', struct.pack('<d', x)[:4])[0]
            self.assertEqual(seed, codec.KEY_SEEDS[index])
        self.assertEqual(codec.key_for_block(0).hex(), '6670844046ee5039b33cc94838527da1')
        self.assertEqual(codec.key_for_block(1).hex(), '685e72a485f9b2fe4dbe386a94b2a921')
        state = 0x12345678
        expected = []
        for _ in range(16):
            state = (state * 0x15A4E35 + 1) % (1 << 32)
            expected.append((state // 65536) % 256)
        self.assertEqual(codec.iv_from_seed(0x12345678), bytes(expected))
        for index in (-1, 2, True, '0'):
            with self.assertRaises(ValueError):codec.key_for_block(index)
        for seed in (-1, 1 << 32, True, '0'):
            with self.assertRaises(ValueError):codec.iv_from_seed(seed)

    def test_full_reconstruction_preserves_every_seed_and_nonzero_padding(self):
        blocks = codec.decode(generated_raw())
        self.assertEqual(codec.encode(blocks), generated_raw())
        self.assertEqual(blocks[0].padding, bytes(range(12)))
        self.assertEqual(blocks[1].padding, b'\xa7')
        self.assertEqual(tuple(b.iv_seed for b in blocks), (0x12345678, 0x87654321))
        for blocks in ([], tuple(reversed(blocks)), (replace(blocks[0], payload=blocks[0].payload[:-1]), blocks[1]),
                       (replace(blocks[0], iv_seed=True), blocks[1])):
            with self.assertRaises(ValueError):codec.encode(blocks)

    def test_actual_byte_length_and_encrypted_endings_are_required(self):
        raw = generated_raw()
        for value in (raw[:-1], raw + b'\0', bytes(codec.FILE_SIZE),
                      memoryview(raw + raw).cast('H'), memoryview(raw).cast('I')):
            with self.subTest(length=len(value)), self.assertRaises(ValueError):codec.decode(value)
        self.assertEqual(codec.decode(memoryview(raw)), codec.decode(raw))
        for offset in (codec.SYSTEM_BLOCK_SIZE - 20, len(raw) - 20):
            damaged = bytearray(raw);damaged[offset] ^= 1
            with self.assertRaises(ValueError):codec.decode(damaged)

    def test_fingerprint_is_explicitly_not_a_payload_checksum(self):
        # CBC corruption far from both encrypted endings still passes their
        # markers. Native serializer proof, not this marker, qualifies writes.
        raw = bytearray(generated_raw());raw[codec.SYSTEM_BLOCK_SIZE + 128] ^= 1
        changed = codec.decode(raw)
        self.assertNotEqual(changed[1].payload, codec.decode(generated_raw())[1].payload)
        self.assertEqual(codec.encode(changed), bytes(raw))
        self.assertIsNone(p.INTEGRITY_KIND)
        changed_seed = bytearray(generated_raw());changed_seed[-4] ^= 1
        seeded = codec.decode(changed_seed)
        self.assertNotEqual(seeded[1].payload[:16], codec.decode(generated_raw())[1].payload[:16])
        self.assertEqual(seeded[1].payload[16:], codec.decode(generated_raw())[1].payload[16:])


class WO4PCFormatTests(unittest.TestCase):
    def setUp(self):
        self.doc = p.decode(generated_raw())
        self.adapter = BoundScalarAdapter(p.GAME_ID, '.bin', p)

    def test_exact_profile_and_one_slot_identity_reject_wrong_editions(self):
        self.assertEqual(self.adapter.serialize(self.doc, {}), generated_raw())
        for game in ('wo4_ultimate_pc', 'wo3u', 'wo4_switch', None):
            with self.subTest(game=game), self.assertRaises(SaveError):p.decode(generated_raw(), game)
        for offset, value in ((0, 20200101), (0, p.REVISION - 1), (4, 1), (8, 1)):
            payload = bytearray(self.doc.payload);struct.pack_into('<I', payload, offset, value)
            with self.assertRaises(SaveError):p.decode(repack(payload))
        for raw in (b'', generated_raw()[:-1], generated_raw() + b'\0', memoryview(generated_raw() * 2).cast('H')):
            with self.assertRaises(SaveError):p.decode(raw)

    def test_all_qualified_fields_surgical_and_no_history_or_gameplay_edit(self):
        fields = p.field_map(self.doc)
        self.assertEqual(len(fields), 35)
        self.assertIn('element_01', fields)
        self.assertNotIn('element_00', fields)
        self.assertNotIn('element_03', fields)
        changes = {f.id:f.minimum for f in fields.values()}
        changed = p.decode(p.serialize(self.doc, changes))
        allowed = {i for f in fields.values() for i in range(f.offset, f.offset + f.size)}
        touched = {i for i, (a, b) in enumerate(zip(self.doc.payload, changed.payload)) if a != b}
        self.assertTrue(touched);self.assertLessEqual(touched, allowed)
        self.assertEqual(changed.payload[codec.SYSTEM_PAYLOAD_SIZE:], self.doc.payload[codec.SYSTEM_PAYLOAD_SIZE:])
        self.assertEqual(changed.raw[codec.SYSTEM_BLOCK_SIZE:], generated_raw()[codec.SYSTEM_BLOCK_SIZE:])
        self.assertEqual(p.inspection_rows(changed)[0], p.inspection_rows(self.doc)[0])
        self.assertEqual(tuple((b.iv_seed,b.padding) for b in changed.blocks),
                         tuple((b.iv_seed,b.padding) for b in self.doc.blocks))

    def test_stage_review_limits_unknown_values_and_no_acquisition(self):
        fields = p.field_map(self.doc)
        for field in fields.values():
            pending = self.adapter.stage(self.doc, {}, field.id, field.minimum)
            self.assertEqual(self.adapter.stage(self.doc, pending, field.id, field.value(self.doc.payload)), {})
            if pending:
                self.assertEqual([(f.id,b,a) for f,b,a in self.adapter.review(self.doc,pending)],
                                 [(field.id,field.value(self.doc.payload),field.minimum)])
            for value in (field.minimum - 1, field.maximum + 1, True, '1'):
                with self.assertRaises(SaveError):self.adapter.stage(self.doc, {}, field.id, value)
        for key in ('element_00','element_03','story','officer_exp','weapon_attack'):
            with self.assertRaises(SaveError):self.adapter.stage(self.doc, {}, key, 1)
        maximum = self.adapter.maximums(self.doc, {})
        self.assertEqual(set(maximum), {'gems','crystals','growth_points'})
        self.assertEqual(self.adapter.limit_values(self.doc, {}, ['element_01']), {})
        payload = bytearray(self.doc.payload)
        struct.pack_into('<I',payload,p.SYSTEM_GLOBAL + 0xCC,123456789)
        unusual = p.decode(repack(payload))
        lowered = self.adapter.stage(unusual, {}, 'gems', 100)
        self.assertEqual(self.adapter.stage(unusual, lowered, 'gems', 123456789), {})
        self.assertNotIn('gems',self.adapter.maximums(unusual,lowered))
        self.assertEqual(self.adapter.limit_values(unusual,lowered,['gems']), {'gems':123456789})
        self.assertEqual(p.serialize(unusual,{}),unusual.raw)

    def test_immutable_snapshots_invalid_pending_and_searchable_inspection(self):
        for attribute, value in (('payload',self.doc.payload[:-1]), ('raw',bytearray(self.doc.raw)),
                                 ('blocks',tuple(reversed(self.doc.blocks))),
                                 ('format',replace(self.doc.format,id='wo4_ultimate_pc'))):
            with self.assertRaises(SaveError):p.serialize(replace(self.doc,**{attribute:value}),{})
        for changes in ([], {'missing':0}, {'gems':True}):
            with self.assertRaises(SaveError):p.maximums(self.doc,changes)
        history,elements,officers,weapons = p.inspection_rows(self.doc)
        self.assertEqual(tuple(len(v) for v in (history,elements,officers,weapons)),(2,64,200,8032))
        self.assertEqual(p.TRAINING_START,0x62E00)
        self.assertEqual(p.RESERVED_START,0x6500F)

    def test_save_backup_restore_source_races_and_live_aliases(self):
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory);source = root / 'copy.bin';source.write_bytes(generated_raw())
            doc = self.adapter.read_save(source)
            edited = self.adapter.save_as(doc,{'gems':42},root / 'edited.bin')
            self.assertEqual(p.field_map(edited)['gems'].value(edited.payload),42)
            self.assertEqual(source.read_bytes(),generated_raw())
            snapshot = self.adapter.backup(doc)
            restored = self.adapter.restore(snapshot,root / 'restored.bin')
            self.assertEqual(restored.read_bytes(),generated_raw())
            with self.assertRaises(FileExistsError):self.adapter.save_as(doc,{},source)
            for folder in ('WARRIORS OROCHI4','WARRIORS OROCHI 4'):
                with self.assertRaises(SaveError):p.read_save(root / 'KoeiTecmo' / folder / 'SAVEDATA.BIN')
            if os.name != 'nt':
                source_alias = root / 'alias.bin';source_alias.symlink_to(source)
                with self.assertRaises(FileExistsError):self.adapter.save_as(doc,{},source_alias)
            corrupted = p.snapshot_backup(generated_raw()[:-1],root / 'invalid.bin',p.GAME_ID,root / 'bad-backups')
            with self.assertRaises(SaveError):p.restore(corrupted,root / 'invalid-restored.bin')
            self.assertFalse((root / 'invalid-restored.bin').exists())
            real_backup = p.backup
            def changing(document):
                result = real_backup(document);source.write_bytes(b'changed externally');return result
            with patch.object(p,'backup',side_effect=changing),self.assertRaises(SaveError):
                p.save_as(doc,{'crystals':0},root / 'raced.bin')
            self.assertFalse((root / 'raced.bin').exists())
            with self.assertRaises(SaveError):p.backup(doc)
            with self.assertRaises(SaveError):p.save_as(doc,{},root / 'changed.bin')

    @unittest.skipUnless(os.environ.get('WO4_PC_SAVE_COPY'),'Private native original WO4 PC copy not selected')
    def test_native_complete_reconstruction_and_all_qualified_edits(self):
        raw = Path(os.environ['WO4_PC_SAVE_COPY']).read_bytes();doc = self.adapter.decode(raw)
        self.assertEqual(codec.encode(doc.blocks),raw)
        self.assertEqual(p.serialize(doc,{}),raw)
        fields = p.field_map(doc)
        self.assertGreater(len(fields),3)
        edited = p.decode(p.serialize(doc,{f.id:f.minimum for f in fields.values()}))
        allowed = {i for f in fields.values() for i in range(f.offset,f.offset + f.size)}
        self.assertLessEqual({i for i,(a,b) in enumerate(zip(doc.payload,edited.payload)) if a!=b},allowed)
        self.assertEqual(edited.raw[codec.SYSTEM_BLOCK_SIZE:],raw[codec.SYSTEM_BLOCK_SIZE:])
        self.assertEqual(p.inspection_rows(edited)[0],p.inspection_rows(doc)[0])
        self.assertEqual(tuple((b.iv_seed,b.padding) for b in doc.blocks),
                         tuple((b.iv_seed,b.padding) for b in edited.blocks))


@unittest.skipUnless(os.name == 'nt' or os.environ.get('DISPLAY'),'Graphical display required')
class WO4PCGuiTests(unittest.TestCase):
    def test_native_open_inspector_search_bulk_undo_review_theme_save_restore(self):
        import tkinter as tk
        from koei_editor.games.wo4.editor import Editor
        root = tk.Tk();root.withdraw()
        try:
            with tempfile.TemporaryDirectory() as directory:
                folder = Path(directory);source=folder / 'copy.bin';target=folder / 'edited.bin'
                native = os.environ.get('WO4_PC_SAVE_COPY')
                raw = Path(native).read_bytes() if native else generated_raw();source.write_bytes(raw)
                editor = Editor(root)
                with patch('koei_editor.shared.verified_gui.filedialog.askopenfilename',return_value=str(source)), \
                     patch('koei_editor.shared.verified_gui.messagebox.showerror') as errors:
                    editor.open();errors.assert_not_called()
                editor.show_inspector();root.update()
                for window in root.winfo_children():
                    if isinstance(window,tk.Toplevel):window.destroy()
                editor.search.set('Gems');root.update()
                self.assertEqual(editor.fields.get_children(),('gems',))
                editor.fields.selection_set('gems');editor.value.set('42');editor.apply_selected()
                self.assertEqual(editor.changes,{'gems':42})
                editor.undo();self.assertEqual(editor.changes,{})
                editor.value.set('42');editor.apply_selected();editor.review()
                for window in root.winfo_children():
                    if isinstance(window,tk.Toplevel):window.destroy()
                editor.apply_theme('Dark')
                with patch('koei_editor.shared.verified_gui.filedialog.asksaveasfilename',return_value=str(target)), \
                     patch('koei_editor.shared.verified_gui.messagebox.showerror') as errors:
                    editor.save_as();errors.assert_not_called()
                self.assertEqual(p.field_map(p.read_save(target))['gems'].value(editor.document.payload),42)
                self.assertEqual(source.read_bytes(),raw)
                snapshot = next((folder / 'WarriorsEditorBackups').glob('*.bin'))
                restored = folder / 'restored.bin'
                with patch('koei_editor.shared.verified_gui.filedialog.askopenfilename',return_value=str(snapshot)), \
                     patch('koei_editor.shared.verified_gui.filedialog.asksaveasfilename',return_value=str(restored)), \
                     patch('koei_editor.shared.verified_gui.messagebox.showerror') as errors:
                    editor.restore();errors.assert_not_called()
                self.assertEqual(restored.read_bytes(),raw)
        finally:root.destroy()
